-- Purpose: original measuring/repacking station silhouettes. API: dashed,scale,pack,gallon,sack. Dependencies: drawing primitives and quantities for visuals only.
local T=require('src.ui.theme'); local O=require('src.ui.draw.outline'); local S=require('src.ui.draw.shapes'); local W=require('src.ui.widgets'); local C=require('src.ui.color'); local Station={}; local g=love.graphics
function Station.dashed(x,y,w,h) g.setColor(C.shade(T.paper)); g.setLineWidth(1.3); for px=x,x+w-7,14 do g.line(px,y,math.min(px+7,x+w),y); g.line(px,y+h,math.min(px+7,x+w),y+h) end; for py=y,y+h-7,14 do g.line(x,py,x,math.min(py+7,y+h)); g.line(x+w,py,x+w,math.min(py+7,y+h)) end end
function Station.sack(x,y,w,h,label) S.sack(x,y,w,h,T.paper); O.rect(x+w*.1,y+h*.39,w*.8,h*.19,T.sage,3); W.text(label,x+w*.15,y+h*.43,21,T.ink,w*.7,'center'); for i=1,12 do O.ellipse(x+w*.18+(i*19%41)/41*w*.64,y+h*.16+(i*7%17)/17*h*.16,3,1,T.mustard,.5) end end
function Station.scale(actual,target,unit,clock,reducedMotion) local ratio=target>0 and actual/target or 0; O.rect(374,372,272,147,T.teal,13); O.rect(488,335,42,49,T.steel,5); O.ellipse(509,328,173,25,T.steel); O.ellipse(509,320,162,23,T.paper); if actual>0 then O.ellipse(509,315,math.min(141,actual/3+28),16,T.paper,.8); for i=1,20 do O.ellipse(410+(i*31%193),310+(i*7%13),3,1,T.mustard,.5) end end; O.ellipse(509,441,72,60,T.paper,1.2); for i=0,10 do local angle=math.pi+i/10*math.pi; O.line({509+math.cos(angle)*57,441+math.sin(angle)*48,509+math.cos(angle)*64,441+math.sin(angle)*55},T.ink,1) end; local sway=reducedMotion and 0 or math.sin((clock or 0)*3)*.02*(1-.8*math.min(1,ratio)); local angle=math.pi+math.max(0,math.min(2,ratio))/2*math.pi+sway; O.line({509,441,509+math.cos(angle)*48,441+math.sin(angle)*42},T.maroon,2.5); O.ellipse(509,441,5,5,T.maroon,1); W.text('TARGET',476,382,12,T.maroon); O.rect(395,479,227,31,T.paper,4); W.text(actual..' '..unit,402,483,22,T.ink,213,'center') end
function Station.gallon(x,y,w,h) S.bottle(x,y,w,h,T.mustard); O.rect(x+w*.43,y+h*.21,w*.28,h*.13,T.paper,4); W.text('OIL',x+w*.2,y+h*.58,22,T.maroon,w*.6,'center') end
function Station.pack(x,y,w,h,actual,target,unit,oil,pouring) local ratio=target>0 and math.min(1,actual/target) or 0; O.polygon({x+10,y,x+w-10,y,x+w,y+h,x,y+h},T.paper,3); local filled=h*.78*ratio; if filled>0 then O.rect(x+5,y+h-filled-4,w-10,filled,oil and T.mustard or T.paper,2,.6); if not oil then for i=1,18 do O.ellipse(x+12+(i*13%29)/29*(w-24),y+h-filled+(i*7%17)/17*(filled-4),2,1,T.wood,.4) end end end; O.line({x+10,y+3,x+w-10,y+3},T.steel,2); O.rect(x+w+16,y,15,h,T.bininner,4); if ratio>0 then O.rect(x+w+19,y+h*(1-ratio),9,h*ratio,T.sage,2,.5) end; O.line({x+w+11,y,x+w+36,y},T.maroon,2); W.text(actual..' '..unit,x-31,y+h+13,22,T.ink,w+63,'center'); if pouring then g.setColor(oil and T.mustard or T.paper); g.setLineWidth(oil and 6 or 10); g.line(x+w*.5,y-116,x+w*.5,y+14) end end
return Station

